      "heroSummary": "佛罗伦萨的空间秩序由阿诺河、红瓦屋顶和布鲁内莱斯基巨型穹顶共同构成。沿南岸山丘登高，文艺复兴古城与远处托斯卡纳山脉形成连续层次；乔托钟楼提供近距离穹顶视角，乌菲兹长廊与波波里园林呈现美第奇家族的建筑和艺术体系。每年春季巴尔迪尼花园紫藤垂落，能够将紫色花幕与城市天际线纳入同一画面。",
