      "heroSummary": "奥尔恰谷是托斯卡纳农业景观与文艺复兴理想秩序共同塑造的世界遗产。丝柏树如深绿色笔触勾勒波浪形麦田，贝尔维德雷农庄在秋季辐射雾中露出屋顶，维塔莱塔小教堂孤立于层叠丘陵之间。春季青麦与红色虞美人、夏季金色谷物、秋季赭色翻耕土地形成截然不同的视觉体系。向北沿锡耶纳丘陵延伸，可进入贝壳形田野广场与圣吉米尼亚诺中世纪石塔群，完整展现托斯卡纳人文地理。",
